package com.govweb.application;
import com.govweb.service.ServiceRepository; import com.govweb.user.UserRepository; import com.govweb.document.*; import com.govweb.notification.*; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import java.util.List; import java.time.Year;
@RestController @RequestMapping("/api/applications") public class ApplicationController {private final ApplicationRepository apps;private final ServiceRepository services;private final UserRepository users;private final CertificateRepository certificates;private final NotificationRepository notifications;public ApplicationController(ApplicationRepository a,ServiceRepository s,UserRepository u,CertificateRepository c,NotificationRepository n){apps=a;services=s;users=u;certificates=c;notifications=n;} record Create(Long serviceId,Long citizenId,String applicantName,String dateOfBirth,String citizenshipNumber,String contactNumber,String address){} record Status(ApplicationStatus status,String remarks){} @GetMapping public List<GovApplication> all(@RequestParam(required=false) Long citizenId){return citizenId==null?apps.findAll():apps.findByCitizenIdOrderByCreatedAtDesc(citizenId);} @PostMapping @ResponseStatus(HttpStatus.CREATED) public GovApplication create(@Valid @RequestBody Create c){var a=new GovApplication();a.setService(services.findById(c.serviceId()).orElseThrow());a.setCitizen(users.findById(c.citizenId()).orElseThrow());a.setApplicantName(c.applicantName());a.setDateOfBirth(c.dateOfBirth());a.setCitizenshipNumber(c.citizenshipNumber());a.setContactNumber(c.contactNumber());a.setAddress(c.address());a.setReferenceNumber("GW-"+Year.now().getValue()+"-"+String.format("%05d",(apps.count()+1)));return apps.save(a);} @PutMapping("/{id}/status") public GovApplication status(@PathVariable Long id,@RequestBody Status s){if(s.remarks()==null||s.remarks().isBlank())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Remarks are required");var a=apps.findById(id).orElseThrow();a.setStatus(s.status());a.setRemarks(s.remarks());a=apps.save(a);var note=new Notification();note.setRecipient(a.getCitizen());note.setTitle(s.status()==ApplicationStatus.APPROVED?"Your document has been approved":"Application decision updated");note.setMessage(s.status()==ApplicationStatus.APPROVED?"Your document has been approved. It is ready to download.":"Your application was declined. Remarks: "+s.remarks());note.setLink(s.status()==ApplicationStatus.APPROVED?"/documents":"/applications");notifications.save(note);if(s.status()==ApplicationStatus.APPROVED&&certificates.findByApplicationId(a.getId()).isEmpty()){var certificate=new Certificate();certificate.setApplication(a);certificate.setCertificateNumber("CERT-"+Year.now().getValue()+"-"+String.format("%05d",a.getId()));certificates.save(certificate);}return a;} @DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable Long id){apps.deleteById(id);} }
